fn acl_token(
    f: &mut Fixture,
    name: &str,
    path: &str,
    capabilities: &[&str],
) -> TestResult<Zeroizing<String>> {
    let policy = format!(
        "path {path:?} {{ capabilities = {} }}",
        serde_json::to_string(capabilities)?
    );
    status(
        &f.admin(
            "PUT",
            &format!("sys/policies/acl/{name}"),
            json!({"policy":policy}),
        )?,
        204,
    );
    let mut issued = f.admin(
        "POST",
        "auth/token/create",
        json!({"policies":[name],"no_default_policy":true,"ttl":"600s"}),
    )?;
    status(&issued, 200);
    assert_eq!(issued.body["auth"]["token_type"], "service");
    assert_eq!(issued.body["auth"]["policies"], json!([name]));
    assert_eq!(issued.body["auth"]["token_policies"], json!([name]));
    let token = secret(&mut issued, "/auth/client_token")?;
    let mut looked = f.admin("POST", "auth/token/lookup", json!({"token":token.as_str()}))?;
    status(&looked, 200);
    assert_eq!(looked.body["data"]["policies"], json!([name]));
    erase_json(&mut looked.body);
    Ok(token)
}

